/* Adapted from the supplied QuizStorm 3D Globe v1. Natural Earth land contours: public domain. */
(()=>{'use strict';
const vertexShaderSource = `
  attribute vec3 aPosition;
  attribute float aPhase;

  uniform float uAngle;
  uniform float uTime;
  uniform float uPointSize;
  uniform float uOpacity;
  uniform vec2 uScale;

  varying float vAlpha;
  varying float vBrightness;

  void main() {
    float cosine = cos(uAngle);
    float sine = sin(uAngle);

    vec3 point = vec3(
      cosine * aPosition.x + sine * aPosition.z,
      aPosition.y,
      -sine * aPosition.x + cosine * aPosition.z
    );

    float visibility = smoothstep(-0.015, 0.055, point.z);
    float rimFade = smoothstep(0.0, 0.18, point.z);
    float localPulse = 1.0;

    // Flip the projected X axis so west appears to the left and east to the right.
    // Without this correction the globe is geographically mirrored.
    gl_Position = vec4(vec2(-point.x, point.y) * uScale, -point.z * 0.12, 1.0);
    gl_PointSize = uPointSize * localPulse * visibility;

    vAlpha = uOpacity * rimFade;
    vBrightness = mix(0.76, 1.0, smoothstep(0.0, 1.0, point.z));
  }
`;

const fragmentShaderSource = `
  precision mediump float;

  uniform float uPulse;

  varying float vAlpha;
  varying float vBrightness;

  void main() {
    float distanceFromCenter = length(gl_PointCoord - vec2(0.5)) * 2.0;
    if (distanceFromCenter > 1.0) discard;

    float core = 1.0 - smoothstep(0.44, 0.72, distanceFromCenter);
    float halo = (1.0 - smoothstep(0.55, 1.0, distanceFromCenter)) * (0.34 + 0.42 * max(0.0, uPulse - 1.0));
    float alpha = (core + halo) * vAlpha * uPulse;

    gl_FragColor = vec4(vec3(1.0), clamp(alpha, 0.0, 1.0));
  }
`;


function compileShader(gl, type, source) {
  const shader = gl.createShader(type);
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const message = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(message || 'Kunde inte kompilera WebGL-shader.');
  }
  return shader;
}

function createProgram(gl) {
  const program = gl.createProgram();
  const vertexShader = compileShader(gl, gl.VERTEX_SHADER, vertexShaderSource);
  const fragmentShader = compileShader(gl, gl.FRAGMENT_SHADER, fragmentShaderSource);

  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);
  gl.deleteShader(vertexShader);
  gl.deleteShader(fragmentShader);

  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const message = gl.getProgramInfoLog(program);
    gl.deleteProgram(program);
    throw new Error(message || 'Kunde inte länka WebGL-programmet.');
  }
  return program;
}


function deterministicPhase(index) {
  const value = Math.sin(index * 12.9898 + 78.233) * 43758.5453;
  return value - Math.floor(value);
}


const LANDMASK='data:image/png;base64,';
class QuizStormBoardGlobe extends HTMLElement {
  static get observedAttributes() { return ['active']; }
  constructor() {
    super();
    this.attachShadow({mode:'open'}).innerHTML=`<style>:host{display:block;contain:strict;pointer-events:none}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}canvas[hidden]{display:none}</style><canvas class="gpu" aria-hidden="true"></canvas><canvas class="still" aria-hidden="true" hidden></canvas>`;
    this.canvas=this.shadowRoot.querySelector('.gpu');
    this.still=this.shadowRoot.querySelector('.still');
    this.motion=matchMedia('(prefers-reduced-motion: reduce)');
    this.frame=0;this.elapsed=0;this.lastTime=null;this.drawCount=0;this.mode='uninitialized';
    this.sync=this.sync.bind(this);this.tick=this.tick.bind(this);
    this.onResize=()=>{this.resize();this.sync();};
    this.onLoss=e=>{e.preventDefault();this.stop();this.program=null;this.buffers=[];this.mode='fallback';this.showStill();};
    this.onRestore=()=>{try{this.setupGL();this.sync();}catch{this.mode='fallback';this.showStill();}};
  }
  connectedCallback() {
    this.connected=true;
    document.addEventListener('visibilitychange',this.sync);
    this.motion.addEventListener('change',this.sync);
    this.canvas.addEventListener('webglcontextlost',this.onLoss);
    this.canvas.addEventListener('webglcontextrestored',this.onRestore);
    this.observer=new ResizeObserver(this.onResize);this.observer.observe(this);
    this.sync();
  }
  disconnectedCallback() {
    this.connected=false;this.stop();this.observer?.disconnect();
    document.removeEventListener('visibilitychange',this.sync);
    this.motion.removeEventListener('change',this.sync);
    this.canvas.removeEventListener('webglcontextlost',this.onLoss);
    this.canvas.removeEventListener('webglcontextrestored',this.onRestore);
  }
  attributeChangedCallback() { if(this.connected)this.sync(); }
  stop(){cancelAnimationFrame(this.frame);this.frame=0;this.lastTime=null;}
  async initialize(){
    this.loading=true;
    try{
      const image=new Image();image.src=LANDMASK;await image.decode();
      const mask=document.createElement('canvas');mask.width=image.naturalWidth;mask.height=image.naturalHeight;
      const ctx=mask.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);
      const data=ctx.getImageData(0,0,mask.width,mask.height).data;
      const samples=matchMedia('(max-width:700px)').matches?34000:52000;
      const positions=[],phases=[],goldenAngle=Math.PI*(3-Math.sqrt(5));
      for(let i=0;i<samples;i++){
        const y=1-2*(i+.5)/samples,r=Math.sqrt(Math.max(0,1-y*y)),longitude=goldenAngle*i;
        const x=Math.cos(longitude)*r,z=Math.sin(longitude)*r;
        const u=(Math.atan2(z,x)/(Math.PI*2)+1.5)%1,v=.5-Math.asin(y)/Math.PI;
        if(data[(Math.min(mask.height-1,Math.floor(v*mask.height))*mask.width+Math.min(mask.width-1,Math.floor(u*mask.width)))*4+3]>=90){positions.push(x,y,z);phases.push(deterministicPhase(i));}
      }
      this.positions=new Float32Array(positions);this.phases=new Float32Array(phases);this.pointCount=phases.length;
      this.gl=this.canvas.getContext('webgl',{alpha:true,antialias:false,depth:false,premultipliedAlpha:true,powerPreference:'low-power'});
      if(this.gl)this.setupGL();else this.mode='fallback';
    }catch(e){this.mode=this.positions?'fallback':'unavailable';console.warn('QuizStorm: globen använder reservläge.',e.message);}
    this.loading=false;this.ready=true;this.resize();this.sync();
    this.dispatchEvent(new CustomEvent('globe-ready',{detail:{mode:this.mode,pointCount:this.pointCount||0},bubbles:true}));
  }
  setupGL(){
    const gl=this.gl;
    if(this.program)gl.deleteProgram(this.program);
    for(const buffer of this.buffers||[])gl.deleteBuffer(buffer);
    this.buffers=[];this.program=createProgram(gl);gl.useProgram(this.program);
    for(const [name,data,size] of [['aPosition',this.positions,3],['aPhase',this.phases,1]]){
      const buffer=gl.createBuffer();this.buffers.push(buffer);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);
      const location=gl.getAttribLocation(this.program,name);gl.enableVertexAttribArray(location);gl.vertexAttribPointer(location,size,gl.FLOAT,false,0,0);
    }
    this.uniforms=Object.fromEntries(['Angle','Time','PointSize','Opacity','Pulse','Scale'].map(n=>[n,gl.getUniformLocation(this.program,'u'+n)]));
    gl.clearColor(0,0,0,0);gl.enable(gl.BLEND);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);
    this.mode='webgl';this.canvas.hidden=false;this.still.hidden=true;this.resize();
  }
  resize(){
    if(!this.ready&&!this.gl)return;
    const box=this.getBoundingClientRect();if(!box.width||!box.height)return;
    // Limit the render surface rather than drawing at uncapped phone pixel density.
    this.ratio=Math.min(window.devicePixelRatio||1,1.5,1280/Math.max(box.width,box.height));
    const width=Math.max(1,Math.round(box.width*this.ratio)),height=Math.max(1,Math.round(box.height*this.ratio));
    if(this.canvas.width!==width||this.canvas.height!==height){this.canvas.width=width;this.canvas.height=height;this.still.width=width;this.still.height=height;}
    if(this.mode==='webgl')this.gl.viewport(0,0,width,height);
  }
  sync(){
    if(!this.connected||!this.hasAttribute('active')||document.hidden){this.stop();return;}
    if(!this.ready){if(!this.loading)this.initialize();return;}
    if(this.mode==='fallback'){this.stop();this.showStill();return;}
    if(this.mode!=='webgl')return;
    if(this.motion.matches){this.stop();this.draw();return;}
    if(!this.frame)this.frame=requestAnimationFrame(this.tick);
  }
  tick(time){
    this.frame=0;
    if(!this.connected||!this.hasAttribute('active')||document.hidden||this.motion.matches||this.mode!=='webgl'){this.sync();return;}
    if(this.lastTime!==null)this.elapsed+=Math.min((time-this.lastTime)/1000,.1);
    this.lastTime=time;this.draw();this.frame=requestAnimationFrame(this.tick);
  }
  geometry(){
    const w=this.canvas.width,h=this.canvas.height,aspect=w/h,size=.91;
    return {angle:15*Math.PI/180-Math.PI/2+this.elapsed*Math.PI*2/360,sx:aspect>=1?size/aspect:size,sy:aspect>=1?size:size*aspect,pointSize:Math.min(4.2,Math.max(1.8,Math.min(w,h)/(this.ratio||1)*.0035))*(this.ratio||1)};
  }
  // 105-second cycle: 83s at baseline, 8s rise, 2s crest, 12s return.
  pulseAt(seconds){
    const phase=((seconds%105)+105)%105;
    const smooth=t=>t*t*(3-2*t);
    if(phase<83)return 1;
    if(phase<91)return 1+1.5*smooth((phase-83)/8);
    if(phase<93)return 2.5;
    return 1+1.5*(1-smooth((phase-93)/12));
  }
  draw(){
    if(this.mode!=='webgl')return;
    const gl=this.gl,u=this.uniforms,g=this.geometry();
    gl.clear(gl.COLOR_BUFFER_BIT);gl.useProgram(this.program);
    gl.uniform1f(u.Angle,g.angle);gl.uniform1f(u.Time,this.elapsed);
    gl.uniform1f(u.PointSize,g.pointSize*(1+.46*((this.motion.matches?1:this.pulseAt(this.elapsed))-1)));gl.uniform1f(u.Opacity,.84);
    gl.uniform1f(u.Pulse,this.motion.matches?1:this.pulseAt(this.elapsed));
    gl.uniform2f(u.Scale,g.sx,g.sy);gl.drawArrays(gl.POINTS,0,this.pointCount);this.drawCount++;
  }
  showStill(){
    if(!this.positions)return;
    this.canvas.hidden=true;this.still.hidden=false;
    const ctx=this.still.getContext('2d'),g=this.geometry(),w=this.still.width,h=this.still.height;
    ctx.clearRect(0,0,w,h);const co=Math.cos(g.angle),si=Math.sin(g.angle);
    for(let i=0;i<this.positions.length;i+=3){const x=this.positions[i],y=this.positions[i+1],z=this.positions[i+2],depth=-si*x+co*z;if(depth<=0)continue;
      ctx.globalAlpha=Math.min(1,depth/.18)*.84;ctx.fillStyle='#ffffff';ctx.beginPath();ctx.arc((1-(co*x+si*z)*g.sx)*w/2,(1-y*g.sy)*h/2,g.pointSize*.32,0,Math.PI*2);ctx.fill();
    }
    ctx.globalAlpha=1;this.drawCount++;
  }
}
customElements.define('quizstorm-board-globe',QuizStormBoardGlobe);

// Independent decoration: game state, questions, timers and sound stay in app.js.
const globe=document.createElement('quizstorm-board-globe');globe.id='board-globe';globe.setAttribute('aria-hidden','true');document.body.insertBefore(globe,document.querySelector('#app'));
function syncBoard(){const active=document.body.classList.contains('playing')&&!!document.querySelector('.board-shell');document.body.classList.toggle('board-atmosphere-active',active);globe.toggleAttribute('active',active);}
new MutationObserver(syncBoard).observe(document.querySelector('#app'),{childList:true});
new MutationObserver(()=>{const active=document.body.classList.contains('playing')&&!!document.querySelector('.board-shell');if(active!==globe.hasAttribute('active'))syncBoard();}).observe(document.body,{attributes:true,attributeFilter:['class']});
window.addEventListener('pagehide',()=>globe.stop());window.addEventListener('pageshow',()=>globe.sync());syncBoard();

})();
